let _cidIdx = null;
const cidadeXY = (nome, uf) => {
  if(!_cidIdx){
    _cidIdx = {};
    for(const l of _CID_RAW.split('\n')){
      const p = l.split('|');
      if(p.length === 4) _cidIdx[p[0] + '|' + p[1]] = [+p[2], +p[3]];
    }
  }
  const k = nrmCidade(nome) + '|' + String(uf || '').toUpperCase().trim();
  return _cidIdx[k] || _cidIdx[ALIAS[k]] || null;
};
const nrmCidade = (s) => String(s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();
/* grafias do ERP que divergem do IBGE — apóstrofo comido e grafia antiga */
