const COL_RENAMES={'SEEDER ORIGINAL':'SEEDER ESSENCIAL'};   // renomes do ERP: antigo → novo
const colRename=(nm)=>{ const n=normalize(nm||''); return COL_RENAMES[n]||nm; };
const colNome = (cod)=>{ const k=String(cod||'').trim(); if(!k) return '';
  // já é nome (contém letra) → devolve como veio (aplicando renomes); senão traduz o código
  if(/[A-Za-z]/.test(k)) return colRename(k);
  const k2=k.padStart(2,'0');
  return COLECAO_MAP[k]||COLECAO_MAP[k2]||('COLECAO '+k); };

