// FORMATAÇÃO DE NÚMEROS
// fmtN  → volume: ponto milhar, sem decimais. Acima de 1M: abrevia (vírgula decimal)
// fmtR  → valor R$: sempre abrevia (K/M com vírgula decimal)
// ─────────────────────────────────────────────────────────────────────────────
// Rollover carteira → mês pedido: mês corrente inclui anteriores; demais só o mês
const _pedMonths = (ym) => {
  if (!ym) return [];
  const now = new Date();
  const cur = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  if (ym !== cur) return [ym];
  const [y,m] = ym.split('-').map(Number);
  const out = [];
  for (let i=0; i<=24; i++){ const dt=new Date(y, m-1-i, 1); out.push(`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}`); }
  return out;
};

// Feriados nacionais BR (fixos + móveis via Páscoa) → dias úteis do mês
const _pascoa = (ano) => {
  const a=ano%19,b=Math.floor(ano/100),c=ano%100,d=Math.floor(b/4),e=b%4,f=Math.floor((b+8)/25),g=Math.floor((b-f+1)/3),h=(19*a+b-d-g+15)%30,i=Math.floor(c/4),k=c%4,l=(32+2*e+2*i-h-k)%7,m=Math.floor((a+11*h+22*l)/451),mes=Math.floor((h+l-7*m+114)/31),dia=((h+l-7*m+114)%31)+1;
  return new Date(ano,mes-1,dia);
};
const _feriadosNac = (ano) => {
  const p=_pascoa(ano); const md=(dt)=>`${dt.getMonth()}-${dt.getDate()}`;
  const add=(base,dias)=>{ const d=new Date(base); d.setDate(d.getDate()+dias); return d; };
  const fixos=['0-1','3-21','4-1','8-7','9-12','10-2','10-15','11-25']; // Jan1,Tiradentes,Trabalho,Independência,Aparecida,Finados,Proclamação,Natal
  const moveis=[md(add(p,-47)),md(add(p,-2)),md(add(p,60))]; // Carnaval(ter), Sexta Santa, Corpus Christi
  return new Set([...fixos,...moveis]);
};
const diasUteisMes = (ano, mes /*0-11*/) => {
  const fer=_feriadosNac(ano); const dim=new Date(ano,mes+1,0).getDate(); let n=0;
  for(let d=1;d<=dim;d++){ const dt=new Date(ano,mes,d); const dow=dt.getDay(); if(dow===0||dow===6) continue; if(fer.has(`${mes}-${d}`)) continue; n++; }
  return n;
};

// ── Presets de coleção (aba Apostas). Defaults; o usuário pode sobrescrever e o override é salvo.
/* Curva de captação em 4 quartis do período: Lançamento · Pico · Sustentação · Cauda.
   Curva única para todas as coleções (definida pelo Cícero): 30/20/30/20. */
