// Disjuntor com RELIGAMENTO. Antes era um booleano permanente: uma única falha
// de rede desligava a nuvem pelo resto da sessão e TODAS as bases seguintes de
// um lote iam calladas pro localStorage — sumiam nas outras máquinas.
let   sbDownAt  = 0;      // instante da queda (0 = ligado)
const SB_RETRY_MS = 20000;
let   sbWarned  = false;  // avisa só 1x
const sbReady   = () => !!(SUPABASE_URL && SUPABASE_KEY)
  && (!sbDownAt || (Date.now() - sbDownAt) > SB_RETRY_MS);
let   sbErro    = null;   // última falha da nuvem — exibida no cabeçalho
const sbTrip    = (e) => {
  const msg = (e && e.message) || String(e);
  const net = !!(e && (e.name === 'TypeError' || /Failed to fetch|NetworkError|Load failed/i.test(msg)));
  if (net) sbDownAt = Date.now();         // rede: desliga por SB_RETRY_MS, depois tenta de novo
  // 401/403 = permissão (RLS). Não desliga: a próxima chamada tenta de novo e
  // o aviso fica visível, em vez de cair calado no armazenamento local.
  sbErro = /40[13]/.test(msg) ? 'PERMISSAO' : net ? 'REDE' : 'ERRO';
  if (typeof window !== 'undefined') window.__sbErro = { tipo: sbErro, msg };
  if (!sbWarned) { console.warn('[sb] indisponível — usando armazenamento local' + (net ? ' (rede/sandbox bloqueou fetch)' : '') + ':', msg); sbWarned = true; }
};
const sbHeaders = () => {
  const h = { apikey: SUPABASE_KEY, 'Content-Type': 'application/json' };
  // Chave nova (sb_publishable_) NÃO vai no Authorization — só a antiga JWT (eyJ...).
  // Comportamento validado em produção: não alterar sem testar em máquina limpa.
  if (SUPABASE_KEY.startsWith('eyJ')) h.Authorization = `Bearer ${SUPABASE_KEY}`;
  return h;
};
const sbGet = async (key) => {
  const url = `${SUPABASE_URL}/rest/v1/${SB_TABLE}?key=eq.${encodeURIComponent(key)}&select=value`;
  const r = await fetch(url, { headers: sbHeaders() });
  if (!r.ok) throw new Error('sbGet ' + r.status);
  const rows = await r.json();
  return rows[0]?.value ?? null;
};
const sbSet = async (key, value) => {
  const r = await fetch(`${SUPABASE_URL}/rest/v1/${SB_TABLE}`, {
    method: 'POST',
    headers: { ...sbHeaders(), Prefer: 'resolution=merge-duplicates,return=minimal' },
    body: JSON.stringify({ key, value, updated_at: new Date().toISOString() }),
  });
  if (!r.ok) throw new Error('sbSet ' + r.status + ' ' + (await r.text().catch(()=>'')));
};

// ── COMPRESSÃO (gzip nativo) ───────────────────────────────────────────────
// O 101L completo dá ~25MB de JSON. Gzip derruba p/ ~3MB → cabe no localStorage
// e o tráfego pro Supabase cai ~8x. Prefixo Z: marca o payload comprimido;
// bases antigas (sem prefixo) continuam sendo lidas normalmente.
const ZPFX = 'Z:';
const zipOk = () => typeof CompressionStream !== 'undefined';
const b64enc = (u8) => { let s=''; const CH=0x8000;
  for(let i=0;i<u8.length;i+=CH) s+=String.fromCharCode.apply(null,u8.subarray(i,i+CH));
  return btoa(s); };
const b64dec = (b) => { const s=atob(b); const u8=new Uint8Array(s.length);
  for(let i=0;i<s.length;i++) u8[i]=s.charCodeAt(i); return u8; };
const zip = async (str) => {
  if (!zipOk()) return str;
  try {
    const cs = new CompressionStream('gzip');
    const blob = new Blob([new TextEncoder().encode(str)]).stream().pipeThrough(cs);
    const buf = await new Response(blob).arrayBuffer();
    return ZPFX + b64enc(new Uint8Array(buf));
  } catch(e) { console.warn('[zip] falhou, salvando cru:', e?.message); return str; }
};
// Navegadores antigos não têm DecompressionStream (Chrome<80, FF<113, Safari<16.4).
// Sem fallback, TODA base comprimida voltava null e a tela pedia upload de novo —
// sem nenhum aviso de que o problema era o navegador.
let _fflate = null;
const fflateGunzip = async (u8) => {
  if (!_fflate) _fflate = await import('https://esm.sh/fflate@0.8.2');
  return new TextDecoder().decode(_fflate.gunzipSync(u8));
};
const unzip = async (val) => {
  if (typeof val !== 'string' || !val.startsWith(ZPFX)) return val;
  const bytes = b64dec(val.slice(ZPFX.length));
  if (typeof DecompressionStream !== 'undefined') {
    try {
      const ds = new DecompressionStream('gzip');
      const blob = new Blob([bytes]).stream().pipeThrough(ds);
      return await new Response(blob).text();
    } catch(e) { console.warn('[unzip] nativo falhou, tentando fflate:', e?.message); }
  } else if (typeof window !== 'undefined' && !window.__unzipAviso) {
    window.__unzipAviso = true;
    console.warn('[unzip] navegador sem DecompressionStream — usando fflate');
  }
  try { return await fflateGunzip(bytes); }
  catch(e) {
    console.error('[unzip] falhou nos dois métodos:', e?.message);
    if (typeof window !== 'undefined') window.__unzipErro = e?.message || 'erro';
    return null;
  }
};

// ── CARIMBO DE ATUALIZAÇÃO DAS BASES ───────────────────────────────────────
// Gravamos ISO (tem ano, minuto e fuso). O formato antigo — "31/07 14:20", sem
// ano — continua sendo lido: base salva mês passado não pode virar "sem data".
const _p2 = (n) => String(n).padStart(2,'0');
const fmtTs = (t) => {
  if (!t) return null;
  const s = String(t);
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) {
    const d = new Date(s);
    if (!isNaN(d)) return `${_p2(d.getDate())}/${_p2(d.getMonth()+1)}/${d.getFullYear()} ${_p2(d.getHours())}:${_p2(d.getMinutes())}`;
  }
  return s;                       // legado: devolve como está
};
const tsMs = (t) => {
  if (!t) return 0;
  const s = String(t);
  if (/^\d{4}-\d{2}-\d{2}T/.test(s)) { const d=new Date(s); return isNaN(d)?0:d.getTime(); }
  // legado "DD/MM HH:MM" ou "DD/MM/AAAA HH:MM"
  const m = s.match(/^(\d{2})\/(\d{2})(?:\/(\d{4}))?\s+(\d{2}):(\d{2})/);
  if (!m) return 0;
  const ano = m[3] ? +m[3] : new Date().getFullYear();
  return new Date(ano, +m[2]-1, +m[1], +m[4], +m[5]).getTime();
};

// Produto de MARCA PRÓPRIA pela referência: SE/NE/TH/RS + dígito.
// Caso Paludo: pedido inteiro de Polo Seeder (SE0101890) caía em PL porque o
