const RX_MARCA_PROPRIA = /^(SE|NE|TH|RS)\d/;
const isMarcaPropriaCod = (cod) => RX_MARCA_PROPRIA.test(String(cod||'').toUpperCase().trim());

// Catálogo único das bases: rótulo + quais abas dependem de cada uma.
