// ── STORAGE KV: Supabase (se configurado) → window.storage → localStorage ──
const sbDiag = { lidas:0, vazias:0, erroLeitura:0, falhaUnzip:0, origem:null };
if (typeof window !== 'undefined') window.__sbDiag = sbDiag;
const storageGet = async (key) => {
  let raw = null;
  if (sbReady()) {
    // Uma retentativa antes de desistir: base grande + rede instável dava
    // 'Failed to fetch', o disjuntor desligava a nuvem e o resto da sessão
    // inteira caía no localStorage — que na máquina do usuário está vazio.
    try { raw = await sbGet(key); if (raw != null) sbDiag.origem = 'nuvem'; }
    catch(e) {
      try {
        await new Promise(r=>setTimeout(r,600));
        raw = await sbGet(key);
        if (raw != null) sbDiag.origem = 'nuvem';
      } catch(e2) { sbDiag.erroLeitura++; sbTrip(e2); }
    }
  }
  if (raw == null && window.storage?.get) {
    const r = await window.storage.get(key).catch(()=>null);
    raw = r?.value ?? null;
  }
  if (raw == null) { try { raw = localStorage.getItem(key); if (raw != null && !sbDiag.origem) sbDiag.origem = 'local'; } catch(e) { raw = null; } }
  if (raw == null) { sbDiag.vazias++; return null; }
  const out = await unzip(raw);
  if (out == null) sbDiag.falhaUnzip++; else sbDiag.lidas++;
  return out;
};
// Devolve 'nuvem' | 'local'. Quem grava PRECISA olhar esse retorno: cair no
// armazenamento local significa que a base não vai aparecer em outra máquina.
const _storageSetRaw = async (key, value) => {
  const payload = await zip(value);   // comprime antes de qualquer backend
  if (sbReady()) {
    try { await sbSet(key, payload); sbErro = null;
      if (typeof window !== 'undefined') window.__sbErro = null;
      return 'nuvem'; }
    catch(e) { sbTrip(e); }
  }
  if (window.storage?.set) { await window.storage.set(key, payload); return 'local'; }
  try { localStorage.setItem(key, payload); } catch(e) {
    // ANTES: ao encher o localStorage, apagava as OUTRAS bases para caber esta.
    // Com a nuvem fora, subir o 101L derrubava o estoque em silêncio e a
    // Cobertura voltava a pedir o arquivo — sem nada indicando o que houve.
    // Agora derruba só o que já está velho e, se ainda não couber, FALHA
    // avisando, em vez de sacrificar base que o usuário acabou de carregar.
    let ok=false;
    try {
      const agora=Date.now();
      Object.keys(localStorage).filter(k=>k.startsWith('gestao:')&&k!==key).forEach(k=>{
        try { const {ts}=JSON.parse(localStorage.getItem(k)||'{}');
          if(ts && (agora-new Date(ts).getTime())>36*3600*1000) localStorage.removeItem(k); } catch(_){}
      });
      localStorage.setItem(key, payload); ok=true;
    } catch(e2) { ok=false; }
    if(!ok){
      if (typeof window!=='undefined') window.__sbErro={tipo:'CHEIO',
        msg:'armazenamento local cheio — a nuvem está fora e não há espaço nesta máquina'};
      throw new Error('localStorage cheio: base não salva (nuvem indisponível)');
    }
  }
  return 'local';
};

// ── FILA SERIAL DE GRAVAÇÃO ────────────────────────────────────────────────
// O upload em lote disparava os handlers a cada 600ms sem esperar o anterior:
// 6 arquivos = 6 POSTs concorrentes no Supabase. Base grande estourava o
// intervalo, o POST dava timeout, o disjuntor abria e o resto do lote não
// chegava na nuvem. Agora sai UM de cada vez — o parse continua paralelo.
let _writeQ = Promise.resolve();
const storageSet = (key, value) => {
  const run = _writeQ.then(() => _storageSetRaw(key, value),
                           () => _storageSetRaw(key, value));
  _writeQ = run.catch(()=>{});   // uma falha não trava a fila
  return run;
};

// 1ª qualidade: "1", "1ª", "1A", "1A QUALIDADE", "PRIMEIRA". Vazio → mantém (sem info).
const isPrimeiraQual = (q) => {
  const s = normalize(String(q||'')).replace(/[^A-Z0-9]/g,'');
  if(!s) return true;
  if(s.includes('PRIMEIRA') || s.startsWith('PRIM')) return true;
  return /^1(?![0-9])/.test(s);
};

// ─────────────────────────────────────────────────────────────────────────────
// LEAD TIME POR SETOR (Leed_Time.xlsx) — fonte oficial do PCP.
// A ORDEM do array é a sequência do fluxo (1..29): manda na exibição dos setores.
// O número é o teto de dias que a OP pode ficar naquele setor.
// ─────────────────────────────────────────────────────────────────────────────
const LT_FLUXO = [
  // [setor, teto de dias, estágio] — ordem do array = sequência do fluxo
  // fonte: Leed_Time.xlsx · aba "Lead time por setor"
  ['PPCP',3,'PRE'],
  ['APROVACAO DE COR',2,'PRE'],
  ['MALHA COMPRADA',45,'PRE'],
  ['TECELAGEM',15,'PRE'],
  ['TINTURARIA',15,'PRE'],
  ['ESTAMPARIA DIGITAL / ROTATIVO',7,'PRE'],
  ['SUBLIMACAO',7,'PRE'],
  ['TESTE MALHA',2,'PRE'],
  ['GRADE/MODELAGEM/CLIENTE',3,'PRE'],
  ['AGUARDANDO CORTE',3,'PRE'],
  ['CORTE',3,'PRE'],
  ['SEPARACAO CORTE',1,'POS'],
  ['AGUARDANDO RETILINEA',2,'POS'],
  ['PREPARACAO MEIA LUA',1,'POS'],
  ['PREPARACAO BOLSO',1,'POS'],
  ['AGUARDANDO PEITILHO',1,'POS'],
  ['AGUARDANDO AVIAMENTOS COSTURA',2,'POS'],
  ['DECORACAO (AG. PARTES)',4,'POS'],
  ['PRE COSTURA',2,'POS'],
  ['CD COSTURA',2,'POS'],
  ['COSTURA',7,'POS'],
  ['FINALIZANDO COSTURA',3,'POS'],
  ['CASEADO/BOTAO',3,'PCS'],
  ['CASEADO',2,'PCS'],
  ['ABERTURA LATERAL MAQUINA',2,'PCS'],
  ['SILK CARIMBO',3,'PCS'],
  ['TERMOCOLANTE',4,'PCS'],
  ['APLIQUE',3,'PCS'],
  ['ESTAMPARIA',3,'PCS'],
  ['BORDADO',3,'PCS'],
  ['AG. LAVANDERIA',1,'PCS'],
  ['LAVANDERIA PECA PRONTA',10,'PCS'],
  ['AGUARDANDO AVIAMENTO EMBALAGEM',3,'PCS'],
  ['INSPECAO DE QUALIDADE',1,'PCS'],
  ['EMBALAGEM',4,'PCS'],
  ['EXPEDICAO',1,'PCS'],
];
// De-para: nome no 3011 → nome na planilha (o ERP grafa diferente em alguns setores)
const LT_ALIAS = {
  'PCP':'PPCP',
  'CASEADO E BOTAO':'CASEADO/BOTAO', 'CASEADO BOTAO':'CASEADO/BOTAO', 'BOTAO':'CASEADO/BOTAO',
  'AGUARDANDO PARTES':'DECORACAO (AG. PARTES)', 'DECORACOES':'DECORACAO (AG. PARTES)',
  'PREPARACAO GOLA/PE DE GOLA':'PRE COSTURA', 'PREPARANDO BOLSO':'PREPARACAO BOLSO',
  'AGUARDANDO AVIAMENTO':'AGUARDANDO AVIAMENTOS COSTURA',
  'AGUARDANDO LAVANDERIA':'AG. LAVANDERIA', 'AG LAVANDERIA':'AG. LAVANDERIA',
  'LAVANDERIA':'LAVANDERIA PECA PRONTA',
  'SILK':'SILK CARIMBO', 'INSPECAO':'INSPECAO DE QUALIDADE',
  'ESTAMPA':'ESTAMPARIA',
  // pré-corte: estampa na malha, antes do corte
  'ESTAMPA DIGITAL':'ESTAMPARIA DIGITAL / ROTATIVO', 'ROTATIVO':'ESTAMPARIA DIGITAL / ROTATIVO',
  'ABERTURA LATERAL MAQUINAS':'ABERTURA LATERAL MAQUINA',
};
// Mutável de propósito: a aba Lead_Time do Parametros.xlsx reconstrói este
// índice em runtime (LT, sequência e estágio). Todos os helpers fecham sobre
// o MESMO objeto, então a mutação in-place propaga para o app inteiro.
// LT_FLUXO hardcoded fica como semente até a planilha chegar.
const _LT_IDX = {};
const _buildLtIdx = (linhas /* [[nome, lt, est], ...] na ordem do fluxo */) => {
  Object.keys(_LT_IDX).forEach(k=>{ delete _LT_IDX[k]; });
  linhas.forEach(([nome,lt,est],i)=>{ _LT_IDX[nome]={lt, seq:i+1, est}; });
};
_buildLtIdx(LT_FLUXO);
const _ltHit = (setor) => {
  const n = normalize(setor||''); if(!n) return null;
  if(_LT_IDX[n]) return _LT_IDX[n];
  const al = LT_ALIAS[n]; if(al && _LT_IDX[al]) return _LT_IDX[al];
  return null;
};
// teto de dias do setor · sem match na planilha devolve null (chamador usa o fallback antigo)
const ltDeSetor  = (setor) => { const h=_ltHit(setor); return h?h.lt:null; };
// estágio do setor: 'PRE' | 'POS' | 'PCS' · null quando fora da planilha
const estDeSetor = (setor) => { const h=_ltHit(setor); return h?h.est:null; };
// posição no fluxo · setor fora da planilha vai pro fim da lista
const seqDeSetor = (setor) => { const h=_ltHit(setor); return h?h.seq:999; };
// ── CAMINHO ESSENCIAL: setores por onde TODA OF passa (rota mínima até expedir).
// Decoração/silk/lavanderia/bordado etc. ficam fora — previsão otimista mas honesta.
// fora (raros): GRADE/MODELAGEM, AGUARDANDO CORTE, FINALIZANDO COSTURA, APROVACAO DE COR, MALHA COMPRADA
// dentro (maioria passa): TESTE MALHA, DECORACAO
const LT_ESSENCIAL=['PPCP','TECELAGEM','TINTURARIA',
  'TESTE MALHA','CORTE','SEPARACAO CORTE','DECORACAO (AG. PARTES)','CD COSTURA',
  'COSTURA','EMBALAGEM','INSPECAO DE QUALIDADE','EXPEDICAO'];
// Prev. calculada = hoje + saldo do setor atual + Σ LT dos setores ESSENCIAIS à frente.
// saldo = max(0, LT do setor − dias já nele): OF estourada não ganha crédito.
// rota da malha: quem está em MALHA COMPRADA nunca passa por TECELAGEM/TINTURARIA
const _rotaEssencial=(setorAtual)=>{
  const puloMalha = normalize(setorAtual||'')==='MALHA COMPRADA';
  return puloMalha ? LT_ESSENCIAL.filter(nm=>nm!=='TECELAGEM'&&nm!=='TINTURARIA') : LT_ESSENCIAL;
};
/* ═══════════════ ROTEIRO REAL POR REFERÊNCIA ═══════════════
   Setores.xlsx  → de-para código Sisplan (10=PPCP, 60=COSTURA…)
   Roteiro.csv   → PRODUTO;SETOR;SETOR;… (a ORDEM das colunas É a sequência)

   O caminho essencial (LT_ESSENCIAL) é uma média: dá o mesmo LT restante para
   uma peça que passa por Prep. Bolso + Abertura Lateral + Caseado e para uma
   que vai direto do Corte à Embalagem — três etapas de diferença. Com o roteiro
   da referência, o LT restante passa a somar só os setores que AQUELA peça
   ainda percorre.

   Cobertura parcial é esperada: referência sem roteiro cai no caminho
   essencial e fica MARCADA (ltEst), para ninguém confundir estimativa
   com cálculo real.                                                       */
const _SETOR_COD = {};                    // 10 → 'PPCP'
const _ROTEIRO   = {};                    // 'SE0101817' → ['PPCP','TECELAGEM',…]
let   _ROT_LINHAS = [];                   // linhas cruas, p/ reprocessar
/* Etapa presente no roteiro mas sem LT na aba Lead_Time. Ignorar somava zero e
   deixava a data MAIS otimista que o caminho essencial — pior que não ter
   roteiro. 2 dias é o piso combinado até o Cleiton cadastrar os reais. */
const LT_ETAPA_PADRAO = 2;
/* Exceções ao piso, por setor (nome normalizado). Vazio hoje: Separação de Corte
   voltou ao piso de 2d por confirmação do Cícero em 08/26. */
const LT_ETAPA_EXCECAO = { 'CD ACABAMENTO': 1 };
/* Capacidade de setor de PASSAGEM, pç/dia. Esses setores mal registram baixa no
   301A — a peça entra e sai no mesmo dia —, então o P90 empírico sai ínfimo e a
   cascata trava o setor em 100% por dezenas de semanas, empurrando promessa que
   a fábrica não tem. Número informado pela operação, não estimado.
   Cadastro no Parametros.xlsx e ajuste na tela vencem este valor. */
const CAP_PASSAGEM = { 'SEPARACAO CORTE': 7000 };
/* Setores que NÃO disputam capacidade: são fila de espera, não centro produtivo.
   Somem do livro e da cascata, mas o LT deles continua contando na data — a peça
   fica parada ali de verdade. Editável no painel Parâmetros. */
const SETORES_ESPERA_PADRAO = [
  'GRADE/MODELAGEM/CLIENTE','AGUARDANDO CORTE','AGUARDANDO RETILINEA',
  'AGUARDANDO PEITILHO','FINALIZANDO COSTURA',
];
/* Tecelagem+Tinturaria e Malha Comprada são caminhos ALTERNATIVOS para a mesma
   necessidade de malha. No livro, mostrar os três ao mesmo tempo espalha a carga
   por linhas que nunca acontecem juntas na mesma peça. A aba escolhe a hipótese
   de suprimento e consolida tudo nela. */
const MALHA_PROPRIA = ['TECELAGEM','TINTURARIA'];
const MALHA_COMPRADA = 'MALHA COMPRADA';
/* Ajustes feitos na tela (persistidos): passam por cima da exceção e do piso.
   O cadastro do Lead_Time (Parametros.xlsx) continua acima de tudo — se o setor
   ganhar LT lá, o padrão deixa de ser consultado. */
const _LT_PAD_OVR = {};
const setLtPadOvr = (obj) => {
  Object.keys(_LT_PAD_OVR).forEach(k=>delete _LT_PAD_OVR[k]);
  Object.entries(obj||{}).forEach(([k,v])=>{ const n=+v; if(n>0) _LT_PAD_OVR[normalize(k)]=n; });
};
const ltEtapaPadraoDe = (nm) => {
  const n = normalize(nm||'');
  return _LT_PAD_OVR[n] ?? LT_ETAPA_EXCECAO[n] ?? LT_ETAPA_PADRAO;
};
/* Códigos digitados errado no cadastro do Sisplan. 'I7' é 17 (CD ACABAMENTO) —
   letra I no lugar do 1. Sem isso a etapa some da rota em silêncio. */
const COD_TYPO = { 'I7':17, 'I0':10, 'I1':11, 'I2':12, 'I3':13, 'I4':14, 'I5':15,
                   'I6':16, 'I8':18, 'I9':19, 'O0':0 };
const _codSetor = (c) => {
  const t = String(c||'').trim().toUpperCase(); if(!t) return null;
  return COD_TYPO[t] ?? (parseInt(t)||null);
};
const _montaRoteiros = () => {
  Object.keys(_ROTEIRO).forEach(k=>delete _ROTEIRO[k]);
  _ROT_LINHAS.forEach(l=>{
    const ref = String(l[0]||'').trim().toUpperCase(); if(!ref) return;
    const seq = l.slice(1).map(_codSetor).filter(Boolean)
      .map(c=>_SETOR_COD[c]).filter(Boolean);
    if (seq.length) _ROTEIRO[ref] = seq;
  });
};
const setSetoresCod = (pares /* [[cod,nome],…] */) => {
  Object.keys(_SETOR_COD).forEach(k=>delete _SETOR_COD[k]);
  pares.forEach(([c,n])=>{ const k=parseInt(c); if(k&&n) _SETOR_COD[k]=normalize(String(n)); });
  _montaRoteiros();   // de-para pode chegar DEPOIS do CSV: remonta em vez de ficar inerte
};
/* merge=true acumula arquivos (Roteiro.csv de Marcas + Roteiro_PL.csv). Sem isso
   o segundo upload apagava o primeiro. Ref repetida: o último arquivo vence. */
const setRoteiros = (linhas /* [[produto, cod, cod, …], …] */, merge=false) => {
  _ROT_LINHAS = merge ? [..._ROT_LINHAS, ...linhas] : [...linhas];
  _montaRoteiros();
};
const roteiroLinhas = () => _ROT_LINHAS;
/* Casa a ref do 3011 com o roteiro. '_M' (mostruário) usa o roteiro da ref-mãe
   enquanto não houver decisão sobre tratá-lo à parte. */
const roteiroDe = (ref) => {
  const r = String(ref||'').trim().toUpperCase(); if(!r) return null;
  return _ROTEIRO[r] || _ROTEIRO[r.replace(/_M$/,'')] || null;
};
const temRoteiro = (ref) => !!roteiroDe(ref);
const roteiroCobertura = () => Object.keys(_ROTEIRO).length;

/* Setores que faltam percorrer, pelo roteiro da referência.
   Devolve {rota, ancorado} ou null.

   O setor atual nem sempre está na rota: o Roteiro do Sisplan cadastra o fluxo
   produtivo e omite as filas (Teste Malha, Separação Corte, Aguardando…), mas o
   WIP posiciona a OF nelas. Medido no 3011 de 08/26: 81 das 716 OFs com roteiro
   (11,3%) caíam no caminho essencial por isso — e o motivo não era roteiro
   errado, era natureza diferente dos dois cadastros.
   Nesses casos ANCORA pela sequência do Lead_Time: segue da primeira etapa da
   rota cujo seq passa do setor atual. ancorado=true para o memorial avisar. */
/* Diagnóstico de por que o roteiro real não está disponível. São três falhas
   diferentes e antes as três apareciam como "nenhum roteiro carregado": sem o
   de-para de setores, sem o CSV, ou com os dois carregados mas os códigos não
   batendo com o Setores.xlsx. */
const roteiroDiag = () => {
  const nCod = Object.keys(_SETOR_COD).length;
  const nLin = _ROT_LINHAS.length;
  const nRef = Object.keys(_ROTEIRO).length;
  if(!nCod && !nLin) return {falha:'SEM_BASE', nCod, nLin, nRef};
  if(!nCod)          return {falha:'SEM_SETORES', nCod, nLin, nRef};
  if(!nLin)          return {falha:'SEM_CSV', nCod, nLin, nRef};
  if(!nRef)          return {falha:'CODIGOS_NAO_BATEM', nCod, nLin, nRef};
  return null;
};
const _restoRoteiroInfo = (ref, setorAtual) => {
  const rota = roteiroDe(ref);
  if(!rota){
    const d = roteiroDiag();
    return d ? d : {falha:'REF_FORA_DO_ROTEIRO', nRef:Object.keys(_ROTEIRO).length};
  }
  const alvo = _ltHit(setorAtual);
  if(!alvo) return {falha:'SETOR_SEM_LT', rotaTotal:rota.length};
  const nAtual = normalize(setorAtual||'');
  const canon  = (x)=>{ const n=normalize(x); return LT_ALIAS[n]||n; };
  const i = rota.findIndex(x=>canon(x)===canon(nAtual));
  if (i>=0) return {rota: rota.slice(i+1).map(canon), ancorado:false};
  const resto = rota.map(canon).filter(nm=>{ const e=_LT_IDX[nm]; return e && e.seq>alvo.seq; });
  if(resto.length) return {rota:resto, ancorado:true};
  return {falha:'ULTIMA_ETAPA', rotaTotal:rota.length};
};
/* usos que só querem a rota: falha vira null, como antes */
const _restoOk = (r) => (r && r.rota) ? r : null;
const _restoDoRoteiro = (ref, setorAtual) => {
  const r = _restoOk(_restoRoteiroInfo(ref, setorAtual)); return r ? r.rota : null;
};
/* Rota da OF a partir de onde ela está, ou o motivo de não ter dado. */
const roteiroRestante = (ref, setorAtual) => _restoRoteiroInfo(ref, setorAtual);
const ROTA_FALHA_TXT = {
  SEM_BASE:'Nem o Setores.xlsx nem o Roteiro.csv foram carregados nesta base.',
  SEM_SETORES:'O Roteiro.csv está carregado, mas o Setores.xlsx não — sem o de-para, os códigos não viram nome de setor e o roteiro fica inerte. Suba o Setores.xlsx.',
  SEM_CSV:'O Setores.xlsx está carregado, mas nenhum Roteiro.csv foi lido. Suba o Roteiro.csv.',
  CODIGOS_NAO_BATEM:'Os dois arquivos estão carregados, mas nenhum código do Roteiro bateu com o Setores.xlsx — confira se o export veio do mesmo cadastro.',
  REF_FORA_DO_ROTEIRO:'A referência não está nos arquivos de Roteiro carregados.',
  SETOR_SEM_LT:'O setor atual não tem LT cadastrado na aba Lead_Time — sem ele não dá para ancorar a rota. Cadastre o setor no Parametros.xlsx.',
  ULTIMA_ETAPA:'A OF está na última etapa da rota — não há mais nada pela frente.',
};

const prevCalcOf = (setorAtual, diasNoSetor, ref) => {
  const h=_ltHit(setorAtual); if(!h) return null;
  const saldo=Math.max(0,(h.lt||0)-(diasNoSetor||0));
  let resto=0;
  const rota=_restoDoRoteiro(ref,setorAtual);
  if (rota) rota.forEach(nm=>{ const e=_LT_IDX[nm]; resto += e ? e.lt : ltEtapaPadraoDe(nm); });  // roteiro real
  else _rotaEssencial(setorAtual).forEach(nm=>{ const e=_LT_IDX[nm]; if(e&&e.seq>h.seq) resto+=e.lt; });
  const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()+saldo+resto);
  return d;
};
/* true quando a data veio do caminho essencial (estimativa), não do roteiro */
const prevCalcEstimada = (setorAtual, ref) => !_restoDoRoteiro(ref, setorAtual);
// versão com memorial de cálculo (p/ o hover da Prev. Calc)
const prevCalcMemo = (setorAtual, diasNoSetor, ref) => {
  const h=_ltHit(setorAtual); if(!h) return null;
  const estourado=(diasNoSetor||0)>(h.lt||0);
  const saldo=Math.max(0,(h.lt||0)-(diasNoSetor||0));
  const info=_restoOk(_restoRoteiroInfo(ref,setorAtual));
  const rota=info?info.rota:null;
  const passos=[
    rota ? `roteiro da ref ${String(ref||'').toUpperCase()} · ${rota.length+1} etapas`
            +(info.ancorado?` · ${tc(setorAtual)} fora da rota — ancorado na sequência do Lead_Time`:'')
         : `⚠ ref ${String(ref||'—').toUpperCase()} sem roteiro — caminho essencial (estimativa)`,
    `${tc(setorAtual)} (atual): ${saldo}d restantes (LT ${h.lt} − ${diasNoSetor||0} no setor${estourado?' · estourado':''})`];
  let resto=0;
  if (rota) rota.forEach(nm=>{ const e=_LT_IDX[nm];
    if(e){ resto+=e.lt; passos.push(`+ ${tc(nm)}: ${e.lt}d`); }
    else { const lp=ltEtapaPadraoDe(nm); resto+=lp; passos.push(`+ ${tc(nm)}: ${lp}d (padrão — sem LT cadastrado)`); } });
  else _rotaEssencial(setorAtual).forEach(nm=>{ const e=_LT_IDX[nm];
    if(e&&e.seq>h.seq){ resto+=e.lt; passos.push(`+ ${tc(nm)}: ${e.lt}d`); } });
  const tot=saldo+resto;
  const d=new Date(); d.setHours(0,0,0,0); d.setDate(d.getDate()+tot);
  passos.push(`= ${tot} dias · ${rota?'roteiro real':'caminho essencial'}`);
  passos.push(`hoje + ${tot}d → ${fmtDd(d)}`);
  return passos.join('\n');
};

// ── FILA EDD × CAPACIDADE ────────────────────────────────────────────────────
// Espera na fila do setor ATUAL: OFs do mesmo setor+empresa ordenadas por data
// de entrega (EDD — regra de Jackson), carga à frente ÷ capacidade pç/dia útil.
// Capacidade é por dia TRABALHADO → converte pra corridos ×7/5 (sem sábado).
// Ajuste: dCalc anda max(0, fila − saldoLT). Fila e LT COMPETEM, não somam —
// o LT (calibrado no dt_setor real) já embute a espera normal; só o excesso empurra.
// Setor sem capacidade cadastrada → fila 0 (degrada pro comportamento atual).
const FILA_FAT = 7/5;
const calcFilaEDD = (lista, capDe) => {
  // lista: [{of, setor, emp, dComp(Date|null), qtd, diasNoSetor}] · capDe(setorCanon, emp) → pç/dia | null
  const grupos = {};
  lista.forEach(o=>{
    const h=_ltHit(o.setor); if(!h) return;
    const k = Object.keys(_LT_IDX).find(x=>_LT_IDX[x]===h);
    const g = `${k}|${o.emp}`;
    (grupos[g]=grupos[g]||{k, emp:o.emp, ofs:[]}).ofs.push(o);
  });
  const out = {};
  Object.values(grupos).forEach(({k, emp, ofs})=>{
    const cap = capDe(k, emp);
    if(!cap){ ofs.forEach(o=>{ out[o.of]=0; }); return; }
    const ord=[...ofs].sort((a,b)=>{
      const ta=a.dComp?a.dComp.getTime():Infinity, tb=b.dComp?b.dComp.getTime():Infinity;
      if(ta!==tb) return ta-tb;                       // EDD: entrega mais cedo primeiro
      return (b.diasNoSetor||0)-(a.diasNoSetor||0);   // empate: quem espera há mais tempo
    });
    let acc=0;
    ord.forEach(o=>{ out[o.of]=Math.round((acc/cap)*FILA_FAT); acc+=(o.qtd||0); });
  });
  return out;
};

// ── Cascata: capacidade disputada em TODA a rota, não só no setor atual ──────
// O calcFilaEDD acima empurra a data pela fila do setor onde a OF está agora; as
// etapas seguintes entram com LT de tabela, como se cada uma tivesse capacidade
// infinita. Aqui a OF disputa vaga em cada etapa do roteiro: o que não cabe na
// semana rola pra frente e empurra as etapas seguintes DAQUELA OF.
// Ordem de atendimento: EDD (entrega mais cedo primeiro), igual ao calcFilaEDD.
// Cada etapa conclui em max(LT, capacidade) — LT e fila competem, não somam.
// Devolve { of: Date } com a conclusão da última etapa.
const calcCascataOF = (lista, capDe) => {
  const hoje = new Date(); hoje.setHours(0,0,0,0);
  const ord = [...lista].sort((a,b)=>{
    const ta=a.dComp?a.dComp.getTime():Infinity, tb=b.dComp?b.dComp.getTime():Infinity;
    if(ta!==tb) return ta-tb;
    return (b.diasNoSetor||0)-(a.diasNoSetor||0);
  });
  const rest = {};                       // `${setor}|${emp}` → capacidade restante por dia útil
  const restaDe = (k, emp, dia, cap) => {
    const g = `${k}|${emp}`;
    if(!rest[g]) rest[g] = [];
    if(rest[g][dia] == null) rest[g][dia] = cap;
    return rest[g][dia];
  };
  const out = {};
  ord.forEach(o=>{
    const h = _ltHit(o.setor); if(!h) return;
    const kAtual = Object.keys(_LT_IDX).find(x=>_LT_IDX[x]===h);
    const etapas = [kAtual, ..._rotaEssencial(o.setor).filter(nm=>{
      const e=_LT_IDX[nm]; return e && e.seq>h.seq;
    })];
    let dia = 0;                          // dia útil corrente, a partir de hoje
    etapas.forEach((k, idx)=>{
      const e = _LT_IDX[k]; if(!e) return;
      const ltCor = idx===0 ? Math.max(0,(e.lt||0)-(o.diasNoSetor||0)) : (e.lt||0);
      const ltUt  = Math.round(ltCor / FILA_FAT);      // LT em dias úteis
      const cap   = capDe(k, o.emp);
      const ini   = dia;
      if(cap){
        let resto = o.qtd || 0;
        let guard = 0;
        while(resto>0 && guard++ < 2000){
          const livre = restaDe(k, o.emp, dia, cap);
          const usa   = Math.min(resto, livre);
          rest[`${k}|${o.emp}`][dia] = livre - usa;
          resto -= usa;
          if(resto>0) dia++;
        }
      }
      dia = Math.max(dia, ini + ltUt) + 1;
    });
    const d = new Date(hoje);
    d.setDate(d.getDate() + Math.round(Math.max(0,dia-1) * FILA_FAT));
    out[o.of] = d;
  });
  return out;
};

// ─────────────────────────────────────────────────────────────────────────────
// Popover de observação (hover no nº do pedido/OF) — usado na PL e na Entregas.
function ObsPopover({pop,label}){
  if(!pop) return null;
  const W = (typeof window!=='undefined'?window.innerWidth:1200);
  return (
    <div style={{position:'fixed',left:Math.min(pop.x, W-360),top:pop.y,zIndex:9999,
      maxWidth:340,background:K.bg1,border:`1px solid ${K.amber}`,borderTop:`3px solid ${K.amber}`,
      borderRadius:10,padding:'10px 12px',boxShadow:'0 6px 24px rgba(0,0,0,0.25)',pointerEvents:'none'}}>
      <div style={{fontSize:14,fontWeight:700,color:K.t2,textTransform:'uppercase',letterSpacing:'0.06em',marginBottom:5}}>
        Obs · {label||'Pedido'} #{pop.num}
      </div>
      <div style={{fontSize:14,color:K.t0,lineHeight:1.5,whiteSpace:'pre-wrap',wordBreak:'break-word'}}>{pop.txt}</div>
    </div>
  );
}
/* ── SALDO DE COLEÇÕES ENCERRADAS ─────────────────────────────────────────
   Hover no card de Estoque. Fica em popover porque é diagnóstico: pesa na
   decisão de outlet, não na leitura diária de comprometimento. */
function SaldoPopover({pop}){
  if(!pop) return null;
  const W=(typeof window!=='undefined'?window.innerWidth:1200);
  const linhas=pop.linhas||[];
  const maxQ=Math.max(1,...linhas.map(x=>x.q));
  return (
    <div style={{position:'fixed',left:Math.min(pop.x, W-420),top:pop.y,zIndex:9999,
      width:390,background:K.bg1,border:`1px solid ${K.border2}`,borderTop:`3px solid ${K.t2}`,
      borderRadius:10,padding:'12px 14px',boxShadow:'0 6px 24px rgba(0,0,0,0.25)',pointerEvents:'none'}}>
      <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:10,
        paddingBottom:8,borderBottom:`1px solid ${K.border}`}}>
        <span style={{fontSize:14,fontWeight:700,color:K.t2,textTransform:'uppercase',letterSpacing:'0.06em'}}>
          Saldo de coleções encerradas</span>
        <span style={{fontSize:14,color:K.t0,fontWeight:700,fontVariantNumeric:'tabular-nums'}}>
          {fmtN(pop.totQ)} pç</span>
      </div>
      <div style={{display:'flex',flexDirection:'column',gap:8,paddingTop:9}}>
        {linhas.slice(0,9).map(x=>(
          <div key={x.nome}>
            <div style={{display:'flex',justifyContent:'space-between',alignItems:'baseline',gap:8,
              fontSize:14,fontVariantNumeric:'tabular-nums'}}>
              <span style={{color:K.t1,overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>
                {tc(x.nome)}</span>
              <span style={{color:K.t0,fontWeight:700,flexShrink:0}}>{fmtN(x.q)}
                <span style={{color:K.t2,fontWeight:400}}> · {fmtR(x.v)}</span></span>
            </div>
            <div style={{height:5,background:K.bg3,borderRadius:3,marginTop:3,overflow:'hidden'}}>
              <div style={{height:'100%',width:`${x.q/maxQ*100}%`,background:K.t2,opacity:.6,borderRadius:3}}/>
            </div>
          </div>
        ))}
      </div>
      {linhas.length>9 && (
        <div style={{fontSize:14,color:K.t2,paddingTop:7}}>+{linhas.length-9} coleções menores</div>
      )}
      <div style={{fontSize:14,color:K.t2,paddingTop:9,lineHeight:1.45,borderTop:`1px solid ${K.border}`,marginTop:9}}>
        Fora do comprometido — peça de coleção encerrada é candidata a outlet,
        não a cobertura de carteira.
      </div>
    </div>
  );
}
/* ── PARTES DA OF ──────────────────────────────────────────────────────────
   OF parada em Decoração (Ag. Partes) está esperando as partes voltarem. O
   3011 traz cada parte como linha própria (fac_parte ≠ 00), com setor,
   fornecedor e dias próprios — é ali que se vê QUEM segura e ONDE cobrar.
   Sem a base de partes carregada mostra aviso: sumir faria parecer que a OF
   não tem partes abertas. */
function PartesPopover({pop}){
  if(!pop) return null;
  const W = (typeof window!=='undefined'?window.innerWidth:1200);
  const linhas = pop.partes||[];
  const pior = linhas[0];
  return (
    <div style={{position:'fixed',left:Math.min(pop.x, W-540),top:pop.y,zIndex:9999,
      maxWidth:520,background:K.bg1,border:`1px solid ${K.border2}`,borderTop:`3px solid ${K.amber}`,
      borderRadius:10,padding:'12px 14px',boxShadow:'0 6px 24px rgba(0,0,0,0.25)',pointerEvents:'none'}}>
      <div style={{fontSize:12,fontWeight:700,color:K.t2,textTransform:'uppercase',
        letterSpacing:'0.05em'}}>OF {pop.num} · onde estão as partes</div>
      {pop.aviso ? (
        <div style={{fontSize:14,color:K.amber,marginTop:6,lineHeight:1.5}}>{pop.aviso}</div>
      ) : (<>
        <div style={{fontSize:12,color:K.t2,marginTop:2,marginBottom:9}}>
          {linhas.length} parte{linhas.length>1?'s':''} aberta{linhas.length>1?'s':''}
          {' '}· {fmtN(linhas.reduce((a,c)=>a+(c.qtd||0),0))} pç
          {' '}· a OF só anda quando a última voltar</div>
        <table style={{borderCollapse:'collapse',fontSize:13,width:'100%'}}>
          <thead><tr style={{color:K.t2,fontSize:11}}>
            <th style={{textAlign:'left',padding:'0 8px 5px 0',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>PARTE</th>
            <th style={{textAlign:'left',padding:'0 8px 5px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>SETOR</th>
            <th style={{textAlign:'left',padding:'0 8px 5px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>FORNECEDOR</th>
            <th style={{textAlign:'right',padding:'0 8px 5px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>PÇ</th>
            <th style={{textAlign:'right',padding:'0 0 5px 8px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>DIAS</th>
          </tr></thead>
          <tbody>
            {linhas.map((l,i)=>{
              const c = l.dias>=21?K.red : l.dias>=10?K.amber : K.t1;
              return (
                <tr key={i}>
                  <td style={{padding:'5px 8px 5px 0',color:i===0?c:K.t1,
                    fontWeight:i===0?700:400,whiteSpace:'nowrap'}}>{l.parte}</td>
                  <td style={{padding:'5px 8px',color:K.t1,whiteSpace:'nowrap'}}>{l.setor}</td>
                  <td style={{padding:'5px 8px',color:K.t2,whiteSpace:'nowrap'}}>{l.fornecedor}</td>
                  <td style={{padding:'5px 8px',textAlign:'right',color:K.t1,whiteSpace:'nowrap',
                    fontVariantNumeric:'tabular-nums'}}
                    title={l.grades>1?`${l.grades} grades somadas`:undefined}>
                    {fmtN(l.qtd||0)}{l.grades>1?<span style={{color:K.t2,fontSize:11}}> ·{l.grades}</span>:null}</td>
                  <td style={{padding:'5px 0 5px 8px',textAlign:'right',color:c,
                    fontWeight:i===0?700:400,fontVariantNumeric:'tabular-nums'}}>{l.dias}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
        {pior && (
          <div style={{borderTop:`1px solid ${K.border}`,marginTop:9,paddingTop:7,
            fontSize:12,color:K.t2}}>
            Segura a OF: <b style={{color:pior.dias>=21?K.red:K.amber}}>
              {pior.parte} · {pior.setor} · {pior.fornecedor} · {fmtN(pior.qtd||0)} pç · {pior.dias}d</b>
          </div>
        )}
      </>)}
    </div>
  );
}

/* Setores de decoração de verdade. O roteiro só nomeia o tipo em ~24% das refs;
   nos outros 77% traz o agregador 'DECORACAO (AG. PARTES)', que não distingue
   bordado de estampa. Quando as partes já saíram, o setor delas diz o tipo. */
const SETORES_DECORACAO = ['BORDADO','ESTAMPARIA','SILK CARIMBO','SUBLIMACAO','TRANSFER',
  'CD BORDADO','CD ESTAMPARIA','CD TRANSFER','CD SUBLIMACAO'];
const ehDecoracaoAgregada = (nm) => /DECORACAO|AG\.? *PARTES/.test(normalize(nm||''));

/* ── ROTEIRO DA OF ─────────────────────────────────────────────────────────
   Rota da referência a partir de onde a OF está: setor atual + o que falta,
   com o LT de cada etapa e a data em que chega. As datas intermediárias somam
   só LT — a fila EDD entra apenas no setor atual, igual ao motor da Dt Prov. */
function RoteiroPopover({pop}){
  if(!pop) return null;
  const W = (typeof window!=='undefined'?window.innerWidth:1200);
  const cor = pop.fonte==='REAL'?K.green : pop.fonte==='ANCORA'?K.amber : K.t2;
  return (
    <div style={{position:'fixed',left:Math.min(pop.x, W-500),top:pop.y,zIndex:9999,
      maxWidth:480,background:K.bg1,border:`1px solid ${K.border2}`,borderTop:`3px solid ${cor}`,
      borderRadius:10,padding:'12px 14px',boxShadow:'0 6px 24px rgba(0,0,0,0.25)',pointerEvents:'none'}}>
      <div style={{fontSize:12,fontWeight:700,color:K.t2,textTransform:'uppercase',letterSpacing:'0.05em'}}>
        OF {pop.num} · {pop.fonte==='EST'?'caminho essencial':'roteiro real'}
        {pop.ref?` — ${pop.ref}`:''}</div>
      {pop.fonte==='EST' ? (
        <div style={{fontSize:13,color:K.t2,marginTop:5,lineHeight:1.5}}>
          <b style={{color:K.amber}}>Por que não usou o roteiro real:</b>{' '}
          {ROTA_FALHA_TXT[pop.falha]||'motivo não identificado.'}
          <br/><span style={{fontSize:11,color:K.t2}}>
            base: {pop.nCod??0} setores no de-para · {pop.nLin??0} linhas de roteiro ·
            {' '}{pop.nRef??0} refs mapeadas</span>
          {pop.temRota && <><br/><span style={{color:K.t2}}>
            A ref <b style={{color:K.t1}}>{pop.ref}</b> TEM roteiro cadastrado
            ({pop.rotaTotal} etapas) — o bloqueio é o setor atual
            <b style={{color:K.t1}}> {pop.setorAtual}</b>.</span></>}
          <br/>A data vem do caminho essencial do Lead_Time.</div>
      ) : (
        <div style={{fontSize:12,color:K.t2,marginTop:2}}>
          {pop.etapas.length} etapa{pop.etapas.length>1?'s':''} até o fim
          {pop.total?` · ${pop.total} no roteiro completo`:''}</div>
      )}
      {pop.ancorado && (
        <div style={{fontSize:12,color:K.amber,marginTop:5,lineHeight:1.5}}>
          ⚓ <b>{pop.setorAtual}</b> não está no roteiro cadastrado — é fila, não etapa
          produtiva. Ancorado na sequência do Lead Time.</div>
      )}
      {pop.etapas.length>0 && (
        <table style={{borderCollapse:'collapse',fontSize:13,width:'100%',marginTop:9}}>
          <thead><tr style={{color:K.t2,fontSize:11}}>
            <th style={{textAlign:'left',padding:'0 6px 5px 0',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>ETAPA</th>
            <th style={{textAlign:'right',padding:'0 6px 5px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>LT</th>
            <th style={{textAlign:'right',padding:'0 0 5px 6px',fontWeight:400,
              borderBottom:`1px solid ${K.border}`}}>CHEGA</th>
          </tr></thead>
          <tbody>
            {pop.etapas.map((e,i)=>{
              const ult=i===pop.etapas.length-1;
              return (
                <tr key={i}>
                  <td style={{padding:'5px 6px 5px 0',whiteSpace:'nowrap',
                    color:e.atual?cor:(ult?K.t0:K.t1),fontWeight:(e.atual||ult)?700:400}}>
                    {e.atual?'▶ ':''}{e.nome}
                    {e.tipos && <span style={{color:K.teal,fontSize:11,fontWeight:400}}>
                      {' '}→ {e.tipos}</span>}
                    {e.atual && <span style={{color:K.t2,fontSize:11,fontWeight:400}}>
                      {' '}atual{e.dias!=null?` · ${e.dias}d no setor`:''}{pop.ancorado?' · fora da rota':''}</span>}
                    {e.padrao && <span style={{color:K.amber,fontSize:11,fontWeight:400}}> padrão</span>}
                  </td>
                  <td style={{padding:'5px 6px',textAlign:'right',
                    color:e.padrao?K.amber:K.t1,fontVariantNumeric:'tabular-nums'}}>{e.lt}d</td>
                  <td style={{padding:'5px 0 5px 6px',textAlign:'right',
                    color:ult?K.t0:K.t2,fontWeight:ult?700:400,
                    fontVariantNumeric:'tabular-nums'}}>{e.chega}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
      <div style={{borderTop:`1px solid ${K.border}`,marginTop:9,paddingTop:7,
        fontSize:12,color:K.t2,lineHeight:1.55}}>
        {pop.fila>0 && <>+ fila {pop.setorAtual}: {pop.fila}d (EDD × capacidade) → </>}
        <b style={{color:K.t1}}>Dt Prov. {pop.dtProv}</b>
        {pop.desvio!=null && <><br/>Prev. Ind {pop.dtPrev} ·{' '}
          <b style={{color:pop.desvio<0?K.red:K.t2}}>
            {pop.desvio<0?`${-pop.desvio}d antes da rota fechar`:`${pop.desvio}d de folga`}</b></>}
        {pop.etapas.length>1 && <><br/><span style={{fontSize:11}}>
          datas do meio somam só LT — fila adiante não entra na conta</span></>}
      </div>
    </div>
  );
}

// MICRO COMPONENTES — novos estilos
// ─────────────────────────────────────────────────────────────────────────────

// ── BARRA DE ATUALIZAÇÃO DAS BASES ─────────────────────────────────────────
// Aparece no topo de TODAS as abas. Mostra só as bases que aquela aba usa
// (ABA_BASES) e destaca as que faltam ou estão defasadas em relação à mais
// recente do conjunto — base velha no meio de bases novas é erro silencioso.
const DEFASAGEM_MS = 24 * 3600 * 1000;
const fmtTsCurto = (t) => {
  const f = fmtTs(t);
  return f ? f.replace(/\/\d{4} /, ' ') : f;   // 31/07/2026 22:25 → 31/07 22:25
};
const BarraBases = ({ lastUpdated, activeDash, baseFiles }) => {
  const keys  = ABA_BASES[activeDash] || BASES_META.map(b => b.key);
  const itens = keys.map(k => ({ key:k, label:BASE_LABEL[k] || k, ts:lastUpdated[k],
    fn:(baseFiles&&baseFiles[k])||null }));
  const comTs = itens.filter(i => i.ts);
  const recMs = comTs.reduce((m,i) => Math.max(m, tsMs(i.ts)), 0);
  const faltam = itens.length - comTs.length;
  const defasada = (ts) => { const d = tsMs(ts); return recMs && d && (recMs - d) > DEFASAGEM_MS; };

  return (
    <div style={{display:'flex',alignItems:'center',gap:8,flex:1,minWidth:0,
      overflowX:'auto',overflowY:'hidden',justifyContent:'center'}}>
      {faltam > 0 && (
        <span style={{fontSize:14,fontWeight:700,color:K.red,background:`${K.red}14`,
          padding:'2px 7px',borderRadius:5,whiteSpace:'nowrap',flexShrink:0}}>
          {faltam} faltando
        </span>
      )}
      {itens.map(i => (
        <span key={i.key}
          title={i.ts ? `${i.label}${i.fn?` · arquivo: ${i.fn}`:''} · atualizada em ${fmtTs(i.ts)}` : `${i.label} · NÃO carregada`}
          style={{display:'flex',alignItems:'center',gap:5,flexShrink:0,whiteSpace:'nowrap',
            border:`1px solid ${i.ts?K.border2:K.red}`,borderRadius:6,padding:'2px 8px'}}>
          <span style={{width:6,height:6,borderRadius:'50%',flexShrink:0,
            background:i.ts?(defasada(i.ts)?K.amber:K.green):K.red}}/>
          <span style={{fontSize:14,fontWeight:600,color:K.t1}}>{i.fn || i.label}</span>
          <span style={{fontSize:14,color:i.ts?(defasada(i.ts)?K.amber:K.t2):K.red}}>
            {i.ts ? fmtTsCurto(i.ts) : 'sem base'}
          </span>
        </span>
      ))}
    </div>
  );
};

