// Multi-select dropdown para filtros Estoque (array multi-select com Ctrl)
const FilterMultiSelect = ({ label, options, values, onChange, multi = true, optionLabels = null, minW = 140 }) => {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef(null);
  React.useEffect(() => {
    const handler = (e) => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);
  const isActive = values.length > 0;
  const displayLabel = isActive
    ? (values.length === 1 ? values[0] : `${values.length} sel.`)
    : `${label}: Todos`;
  const toggle = (opt, ctrl) => {
    if (!multi || !ctrl) {
      // Click simples: seleciona apenas essa opção e fecha
      if (values.length === 1 && values[0] === opt) { onChange([]); setOpen(false); return; }
      onChange([opt]);
      setOpen(false);
      return;
    }
    // Ctrl/Cmd: toggle múltiplo, mantém aberto
    onChange(values.includes(opt) ? values.filter(v => v !== opt) : [...values, opt]);
  };
  const ORANGE = K.green;
  const GREEN = K.green; // verde de seleção ativa
  return (
    <div ref={ref} style={{ position:'relative', flex:'1 1 0', minWidth:minW }}>
      <button onClick={() => setOpen(o => !o)} style={{
        display:'flex', alignItems:'center', justifyContent:'space-between', gap:7,
        height:30, padding:'0 10px', width:'100%',
        borderRadius:7, cursor:'pointer', fontFamily:K.font,
        background: isActive ? `${GREEN}15` : K.bg2,
        border: `1px solid ${isActive ? GREEN : K.border2}`,
        color: isActive ? GREEN : K.t1,
        fontSize:14, fontWeight: isActive ? 600 : 500,
        whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis',
      }}>
        <span style={{overflow:'hidden',textOverflow:'ellipsis'}}>{displayLabel}</span>
        <ChevronDown size={12} color={isActive ? GREEN : K.t2}/>
      </button>
      {open && (
        <div style={{
          position:'absolute', top:'calc(100% + 4px)', left:0, right:0, zIndex:50,
          background:K.bg1, border:`1px solid ${ORANGE}`, borderRadius:12,
          boxShadow:'0 8px 32px rgba(0,0,0,0.15)', minWidth:220, maxHeight:320,
          overflowY:'auto', padding:'6px 4px',
        }}>
          <div onClick={() => { onChange([]); setOpen(false); }}
            style={{ display:'flex', alignItems:'center', gap:8, padding:'8px 12px',
              cursor:'pointer', background: !isActive ? K.greenD : 'transparent',
              borderRadius:6, margin:'2px 0' }}>
            <span style={{ width:14, height:14, borderRadius:3,
              border:`1px solid ${!isActive ? ORANGE : K.border2}`,
              background: !isActive ? ORANGE : 'transparent',
              display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
              {!isActive && <span style={{color:'#fff',fontSize:14,lineHeight:1,fontWeight:700}}>✓</span>}
            </span>
            <span style={{ fontSize:14, color: !isActive ? ORANGE : K.t1, fontWeight: !isActive ? 600 : 500 }}>TODOS</span>
          </div>
          {options.map(opt => {
            const checked = values.includes(opt);
            return (
              <div key={opt} onClick={(e) => toggle(opt, e.ctrlKey || e.metaKey)}
                style={{ display:'flex', alignItems:'center', gap:8, padding:'8px 12px',
                  cursor:'pointer', background: checked ? K.greenD : 'transparent',
                  borderRadius:6, margin:'2px 0' }}>
                <span style={{ width:14, height:14, borderRadius:3,
                  border:`1px solid ${checked ? ORANGE : K.border2}`,
                  background: checked ? ORANGE : 'transparent',
                  display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
                  {checked && <span style={{color:'#fff',fontSize:14,lineHeight:1,fontWeight:700}}>✓</span>}
                </span>
                <span style={{ fontSize:14, color: checked ? ORANGE : K.t1, fontWeight: checked ? 600 : 500 }}>
                  {opt}{optionLabels&&optionLabels[opt]!=null?<span style={{color:K.t2,fontWeight:500}}> ({optionLabels[opt]})</span>:null}
                </span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};


